mapper.update:
update im_channel set status=1,archive_reason=#{reason},archived_at=#{now},opt_in_default=0,
    perm_version=perm_version+1,update_time=#{now}
where id=#{row.id} and guild_kind=#{row.guildKind} and guild_id=#{row.guildId}
  and status=0 and del_flag=0 and perm_version=#{row.permissionVersion} and perm_version < 2147483647

update im_channel set status=0,archive_reason=null,archived_at=null,
    perm_version=perm_version+1,update_time=#{now}
where id=#{row.id} and guild_kind=#{row.guildKind} and guild_id=#{row.guildId}
  and status=1 and archive_reason='manual' and del_flag=0
  and perm_version=#{row.permissionVersion} and perm_version < 2147483647
